describe('Internet Connection Drop Message', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should display a friendly message when the internet connection drops', () => {
        // Simulate dropping the internet connection
        cy.intercept('GET', '**/*', { forceNetworkError: true }).as('networkError');

        // Trigger an action that requires internet connection
        cy.get('button#fetchData').click(); // Replace with the actual button that fetches data

        // Wait for the network error to occur
        cy.wait('@networkError');

        // Assert that the friendly message is displayed
        cy.get('.error-message') // Replace with the actual selector for the error message
          .should('be.visible')
          .and('contain', 'Oops! It seems like your internet connection is down. Please check your connection and try again.');
    });

    it('should not display the message if the internet connection is stable', () => {
        // Simulate a stable internet connection
        cy.intercept('GET', '**/*', { statusCode: 200 }).as('stableConnection');

        // Trigger an action that requires internet connection
        cy.get('button#fetchData').click(); // Replace with the actual button that fetches data

        // Wait for the stable connection response
        cy.wait('@stableConnection');

        // Assert that the friendly message is not displayed
        cy.get('.error-message') // Replace with the actual selector for the error message
          .should('not.exist');
    });
});
